def hidden_rule_fn(state):
    n = len(state)
    a = state[n-2]
    b = state[n-1]

    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, x):
            if x % i == 0:
                return False
        return True

    if is_prime(n):
        return (a ^ b) % 7
    else:
        # For non-prime positions, use grolp-sum
        s = a + b
        if s == 6:
            return (s + 5) % 7
        return (s + 3) % 7
